import{_ as t,a0 as o,w as d,s as c,I as a,x as n,a1 as l,A as p,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"32 位支持：使用 GCC 交叉编译 | LCTT x X-CMD","titleTemplate":false,"description":"32 位支持：使用 GCC 交叉编译 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"32 位支持：使用 GCC 交叉编译 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"32 位支持：使用 GCC 交叉编译 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190710 32-bit life support- Cross-compiling with GCC","title":"32 位支持：使用 GCC 交叉编译","tag":"201907","desc":""},"relativePath":"201907/20190710 32-bit life support- Cross-compiling with GCC.md","filePath":"[post].md"}'),r={name:"201907/20190710 32-bit life support- Cross-compiling with GCC.md"};function u(g,s,b,h,k,C){const i=o("Link");return d(),c("div",null,[s[29]||(s[29]=a("h1",{id:"_32-位支持-使用-gcc-交叉编译",tabindex:"-1"},[n("32 位支持：使用 GCC 交叉编译 "),a("a",{class:"header-anchor",href:"#_32-位支持-使用-gcc-交叉编译","aria-label":"Permalink to “32 位支持：使用 GCC 交叉编译”"},"​")],-1)),s[30]||(s[30]=a("blockquote",null,[a("p",null,"使用 GCC 在单一的构建机器上来为不同的 CPU 架构交叉编译二进制文件。")],-1)),s[31]||(s[31]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/19/054242nwhludz9tm2lwd8t.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("如果你是一个开发者，要创建二进制软件包，像一个 RPM、DEB、Flatpak 或 Snap 软件包，你不得不为各种不同的目标平台编译代码。典型的编译目标包括 32 位和 64 位的 x86 和 ARM。你可以在不同的物理或虚拟机器上完成你的构建，但这需要你为何几个系统。作为代替，你可以使用 GNU 编译器集合 (",-1)),l(i,{href:"https://gcc.gnu.org/"},{default:p(()=>[...s[0]||(s[0]=[n("GCC",-1)])]),_:1}),s[2]||(s[2]=n(") 来交叉编译，在单一的构建机器上为几个不同的 CPU 架构产生二进制文件。",-1))]),s[32]||(s[32]=e(`<p>假设你有一个想要交叉编译的简单的掷骰子游戏。在大多数系统上，以 C 语言来编写这个相对简单，出于给添加现实的复杂性的目的，我以 C++ 语言写这个示例，所以程序依赖于一些不在 C 语言中东西 (具体来说就是 <code>iostream</code>)。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;iostream&gt;</span></span>
<span class="line"><span>#include &lt;cstdlib&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using namespace std;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void lose (int c); </span></span>
<span class="line"><span>void win (int c); </span></span>
<span class="line"><span>void draw (); </span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() { </span></span>
<span class="line"><span>  int i; </span></span>
<span class="line"><span>    do { </span></span>
<span class="line"><span>      cout &lt;&lt; &quot;Pick a number between 1 and 20: \\n&quot;; </span></span>
<span class="line"><span>      cin &gt;&gt; i; </span></span>
<span class="line"><span>      int c = rand ( ) % 21; </span></span>
<span class="line"><span>      if (i &gt; 20) lose (c); </span></span>
<span class="line"><span>      else if (i &lt; c ) lose (c); </span></span>
<span class="line"><span>      else if (i &gt; c ) win (c); </span></span>
<span class="line"><span>      else draw (); </span></span>
<span class="line"><span>      } </span></span>
<span class="line"><span>      while (1==1); </span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void lose (int c ) </span></span>
<span class="line"><span>  { </span></span>
<span class="line"><span>    cout &lt;&lt; &quot;You lose! Computer rolled &quot; &lt;&lt; c &lt;&lt; &quot;\\n&quot;; </span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void win (int c ) </span></span>
<span class="line"><span>  { </span></span>
<span class="line"><span>    cout &lt;&lt; &quot;You win!! Computer rolled &quot; &lt;&lt; c &lt;&lt; &quot;\\n&quot;; </span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void draw ( ) </span></span>
<span class="line"><span>   { </span></span>
<span class="line"><span>     cout &lt;&lt; &quot;What are the chances. You tied. Try again, I dare you! \\n&quot;;</span></span>
<span class="line"><span>   }</span></span></code></pre></div><p>在你的系统上使用 <code>g++</code> 命令编译它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ g++ dice.cpp -o dice</span></span></code></pre></div><p>然后，运行它来确认其工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./dice</span></span>
<span class="line"><span>Pick a number between 1 and 20:</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你可以使用 <code>file</code> 命令来查看你刚刚生产的二进制文件的类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file ./dice</span></span>
<span class="line"><span>dice: ELF 64-bit LSB executable, x86-64, version 1 (SYSV), dynamically</span></span>
<span class="line"><span>linked (uses shared libs), for GNU/Linux 5.1.15, not stripped</span></span></code></pre></div><p>同样重要，使用 <code>ldd</code> 命令来查看它链接哪些库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd dice</span></span>
<span class="line"><span>linux-vdso.so.1 =&amp;gt; (0x00007ffe0d1dc000)</span></span>
<span class="line"><span>libstdc++.so.6 =&amp;gt; /usr/lib/x86_64-linux-gnu/libstdc++.so.6</span></span>
<span class="line"><span>(0x00007fce8410e000)</span></span>
<span class="line"><span>libc.so.6 =&amp;gt; /lib/x86_64-linux-gnu/libc.so.6</span></span>
<span class="line"><span>(0x00007fce83d4f000)</span></span>
<span class="line"><span>libm.so.6 =&amp;gt; /lib/x86_64-linux-gnu/libm.so.6</span></span>
<span class="line"><span>(0x00007fce83a52000)</span></span>
<span class="line"><span>/lib64/ld-linux-x86-64.so.2 (0x00007fce84449000)</span></span>
<span class="line"><span>libgcc_s.so.1 =&amp;gt; /lib/x86_64-linux-gnu/libgcc_s.so.1</span></span>
<span class="line"><span>(0x00007fce8383c000)</span></span></code></pre></div><p>从这些测试中，你已经确认了两件事：你刚刚运行的二进制文件是 64 位的，并且它链接的是 64 位库。</p><p>这意味着，为实现 32 位交叉编译，你必需告诉 <code>g++</code> 来：</p><ol><li>产生一个 32 位二进制文件</li><li>链接 32 位库，而不是 64 位库</li></ol><h3 id="设置你的开发环境" tabindex="-1">设置你的开发环境 <a class="header-anchor" href="#设置你的开发环境" aria-label="Permalink to “设置你的开发环境”">​</a></h3>`,14)),a("p",null,[s[4]||(s[4]=n("为编译成 32 位二进制，你需要在你的系统上安装 32 位的库和头文件。如果你运行一个纯 64 位系统，那么，你没有 32 位的库或头文件，并且需要安装一个基础集合。最起码，你需要 C 和 C++ 库（",-1)),s[5]||(s[5]=a("code",null,"glibc",-1)),s[6]||(s[6]=n(" 和 ",-1)),s[7]||(s[7]=a("code",null,"libstdc++",-1)),s[8]||(s[8]=n("）以及 GCC 库（",-1)),s[9]||(s[9]=a("code",null,"libgcc",-1)),s[10]||(s[10]=n("）的 32 位版本。这些软件包的名称可能在每个发行版中不同。在 Slackware 系统上，一个纯 64 位的带有 32 位兼容的发行版，可以从 ",-1)),l(i,{href:"http://www.slackware.com/~alien/multilib/"},{default:p(()=>[...s[3]||(s[3]=[n("Alien BOB",-1)])]),_:1}),s[11]||(s[11]=n(" 提供的 ",-1)),s[12]||(s[12]=a("code",null,"multilib",-1)),s[13]||(s[13]=n(" 软件包中获得。在 Fedora、CentOS 和 RHEL 系统上：",-1))]),s[33]||(s[33]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum install libstdc++-*.i686</span></span>
<span class="line"><span>$ yum install glibc-*.i686</span></span>
<span class="line"><span>$ yum install libgcc.i686</span></span></code></pre></div><p>不管你正在使用什么系统，你同样必须安装一些你工程使用的 32 位库。例如，如果你在你的工程中包含 <code>yaml-cpp</code>，那么，在编译工程前，你必需安装 <code>yaml-cpp</code> 的 32 位版本，或者，在很多系统上，安装 <code>yaml-cpp</code> 的开发软件包（例如，在 Fedora 系统上的 <code>yaml-cpp-devel</code>）。</p><p>一旦这些处理好了，编译是相当简单的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ g++ -m32 dice.cpp -o dice32 -L /usr/lib -march=i686</span></span></code></pre></div><p><code>-m32</code> 标志告诉 GCC 以 32 位模式编译。<code>-march=i686</code> 选项进一步定义来使用哪种最优化类型（参考 <code>info gcc</code> 了解选项列表）。<code>-L</code> 标志设置你希望 GCC 来链接的库的路径。对于 32 位来说通常是 <code>/usr/lib</code>，不过，这依赖于你的系统是如何设置的，它可以是 <code>/usr/lib32</code>，甚至 <code>/opt/usr/lib</code>，或者任何你知道存放你的 32 位库的地方。</p><p>在代码编译后，查看你的构建的证据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file ./dice32</span></span>
<span class="line"><span>dice: ELF 32-bit LSB executable, Intel 80386, version 1 (SYSV),</span></span>
<span class="line"><span>dynamically linked (uses shared libs) [...]</span></span></code></pre></div><p>接着，当然， <code>ldd ./dice32</code> 也会指向你的 32 位库。</p><h3 id="不同的架构" tabindex="-1">不同的架构 <a class="header-anchor" href="#不同的架构" aria-label="Permalink to “不同的架构”">​</a></h3><p>在 64 位相同的处理器家族上允许 GCC 做出很多关于如何编译代码的假设来编译 32 位软件。如果你需要为完全不同的处理器编译，你必需安装适当的交叉构建实用程序。安装哪种实用程序取决于你正在编译的东西。这个过程比为相同的 CPU 家族编译更复杂一点。</p><p>当你为相同处理器家族交叉编译时，你可以期待找到与 32 位库集的相同的 64 位库集，因为你的 Linux 发行版是同时维护这二者的。当为一个完全不同的架构编译时，你可能不得不穷追你的代码所需要的库。你需要的版本可能不在你的发行版的存储库中，因为你的发行版可能不为你的目标系统提供软件包，或者它不在容易到达的位置提供所有的软件包。如果你正在编译的代码是你写的，那么你可能非常清楚它的依赖关系是什么，并清楚在哪里找到它们。如果代码是你下载的，并需要编译，那么你可能不熟悉它的要求。在这种情况下，研究正确编译代码需要什么（它们通常被列在 <code>README</code> 或 <code>INSTALL</code> 文件中，当然也出现在源文件代码自身之中），然后收集需要的组件。</p><p>例如，如果你需要为 ARM 编译 C 代码，你必须首先在 Fedora 或 RHEL 上安装 <code>gcc-arm-linux-gnu</code>（32 位）或 <code>gcc-aarch64-linux-gnu</code>（64 位）；或者，在 Ubuntu 上安装 <code>arm-linux-gnueabi-gcc</code> 和 <code>binutils-arm-linux-gnueabi</code>。这提供你需要用来构建（至少）一个简单的 C 程序的命令和库。此外，你需要你的代码使用的任何库。你可以在惯常的位置（大多数系统上在 <code>/usr/include</code>）放置头文件，或者，你可以放置它们在一个你选择的目录，并使用 <code>-I</code> 选项将 GCC 指向它。</p><p>当编译时，不使用标准的 <code>gcc</code> 或 <code>g++</code> 命令。作为代替，使用你安装的 GCC 实用程序。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ arm-linux-gnu-g++ dice.cpp \\</span></span>
<span class="line"><span>  -I/home/seth/src/crossbuild/arm/cpp \\</span></span>
<span class="line"><span>  -o armdice.bin</span></span></code></pre></div><p>验证你构建的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file armdice.bin</span></span>
<span class="line"><span>armdice.bin: ELF 32-bit LSB executable, ARM, EABI5 version 1 (SYSV) [...]</span></span></code></pre></div><h3 id="库和可交付结果" tabindex="-1">库和可交付结果 <a class="header-anchor" href="#库和可交付结果" aria-label="Permalink to “库和可交付结果”">​</a></h3><p>这是一个如何使用交叉编译的简单的示例。在真实的生活中，你的源文件代码可能产生的不止于一个二进制文件。虽然你可以手动管理，在这里手动管理可能不是好的正当理由。在我接下来的文章中，我将说明 GNU 自动工具，GNU 自动工具做了使你的代码可移植的大部分工作。</p><hr>`,19)),a("p",null,[s[15]||(s[15]=n("via: ",-1)),l(i,{href:"https://opensource.com/article/19/7/cross-compiling-gcc"},{default:p(()=>[...s[14]||(s[14]=[n("https://opensource.com/article/19/7/cross-compiling-gcc",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=n("作者：",-1)),l(i,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[16]||(s[16]=[n("Seth Kenlon",-1)])]),_:1}),s[21]||(s[21]=n(" 选题：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[17]||(s[17]=[n("lujun9972",-1)])]),_:1}),s[22]||(s[22]=n(" 译者：",-1)),l(i,{href:"https://github.com/robsean"},{default:p(()=>[...s[18]||(s[18]=[n("robsean",-1)])]),_:1}),s[23]||(s[23]=n(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:p(()=>[...s[19]||(s[19]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[26]||(s[26]=n("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[24]||(s[24]=[n("LCTT",-1)])]),_:1}),s[27]||(s[27]=n(" 原创编译，",-1)),l(i,{href:"https://linux.cn/"},{default:p(()=>[...s[25]||(s[25]=[n("Linux中国",-1)])]),_:1}),s[28]||(s[28]=n(" 荣誉推出",-1))])])}const y=t(r,[["render",u]]);export{x as __pageData,y as default};
